def find_man_on_phone(image, question="Is the man holding a phone?"):
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    phone_patches = image_patch.find("phone")

    for man_patch in man_patches:
        for phone_patch in phone_patches:
            if man_patch.overlaps_with(phone_patch.left, phone_patch.lower, phone_patch.right, phone_patch.upper):
                return man_patch.llm_query(question, long_answer=False)

    return "No man on phone found in the image."

